using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Cosmos DB indexes are no longer configured via EF.
        // HasIndex() now throws; remove it. Manage indexes in Azure portal instead.
        // modelBuilder.Entity<Blog>().HasIndex(b => b.Name); // REMOVED

        // Breaking change 2: Discriminator property renamed from "Discriminator" to "$type".
        // To read existing documents that use "Discriminator", restore the old convention:
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 3: Id format changed from "EntityType|Key" to just "Key".
        // To read existing documents with id="Blog|1", restore the old id format:
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<LegacyCosmosIdGenerator>();

        // Breaking change 4: Raw SQL queries using c.Discriminator must be updated
        // to use the new "$type" property, OR keep the old name as configured above.
        // Since we restored "Discriminator" above, existing SQL remains valid.
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; }

}

// Value generator that preserves the legacy "EntityType|Key" id format
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class LegacyCosmosIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
        => $"{entry.Metadata.ShortName()}|{entry.Property("Id").CurrentValue}";
}

